/**
 * What an alias can behave as, and the parts each kind is made of.
 *
 * An alias is one entity whose state is put together from **parts**: one part per field of the
 * capabilities its domain carries (a thermostat's target, mode, action…). Each part takes its
 * value from a source of its own (`alias-parts.ts`). This file is the one list of types and parts
 * the interface, the file format, the API and `core` share: generated by hand from
 * `DOMAIN_CAPABILITIES` and `CAPABILITY_DEFINITIONS`, and a test fails when a domain, a capability
 * or a state field is left out, so a capability added later cannot be forgotten here.
 */
import {
  FAN_DIRECTIONS,
  LAWN_MOWER_ACTIVITIES,
  PLAYBACK_STATES,
  REPEAT_MODES,
  THERMOSTAT_ACTIONS,
  THERMOSTAT_MODES,
  VACUUM_ACTIVITIES,
  VACUUM_CLEAN_MODES,
  type CapabilityName,
} from './capabilities.js';
import type { EntityDomain } from './entity-id.js';

/**
 * What a part's value is.
 *
 * - `number`, `boolean`, `text`: a scalar.
 * - `enum`: one name of a list - fixed by the capability (a thermostat's modes) or offered by the
 *   alias itself (its presets).
 * - `color`: hue and saturation together.
 * - `picture`: a picture another entity owns (a camera's snapshot, a cover art, a map).
 * - `rooms`: a robot vacuum's rooms, which only the robot knows.
 * - `press`: no value at all: a button's press, seen as the moments it happened.
 */
export const ALIAS_PART_KINDS = [
  'number',
  'boolean',
  'enum',
  'text',
  'color',
  'picture',
  'rooms',
  'press',
] as const;

/** What a part's value is. */
export type AliasPartKind = (typeof ALIAS_PART_KINDS)[number];

/** Where a part takes its value from. */
export const ALIAS_SOURCES = ['stored', 'entity', 'entities', 'formula', 'code'] as const;

/** Where a part takes its value from. */
export type AliasSource = (typeof ALIAS_SOURCES)[number];

/** The sources each kind of part can take: a picture can only be another entity's. */
export const ALIAS_SOURCES_BY_KIND: Readonly<Record<AliasPartKind, readonly AliasSource[]>> = {
  number: ['stored', 'entity', 'entities', 'formula', 'code'],
  boolean: ['stored', 'entity', 'entities', 'formula', 'code'],
  enum: ['stored', 'entity', 'entities', 'formula', 'code'],
  text: ['stored', 'entity', 'entities', 'formula', 'code'],
  color: ['stored', 'entity', 'entities', 'code'],
  picture: ['entity'],
  rooms: ['entity'],
  press: ['stored', 'entity', 'entities'],
};

/** How several entities make one value, by the kind of value. */
export const ALIAS_RULES_BY_KIND: Readonly<Record<AliasPartKind, readonly AliasRule[]>> = {
  number: ['average', 'min', 'max', 'sum'],
  boolean: ['any', 'all'],
  enum: ['first'],
  text: ['first'],
  color: ['first'],
  picture: [],
  rooms: [],
  press: ['all'],
};

/** How several entities make one value. */
export const ALIAS_RULES = ['any', 'all', 'average', 'min', 'max', 'sum', 'first'] as const;

/** How several entities make one value. */
export type AliasRule = (typeof ALIAS_RULES)[number];

/**
 * The settings a part carries besides its source, by what they mean:
 *
 * - `range`: lowest, highest and step (a thermostat's target, a number).
 * - `offered`: the names it offers, when the list is the alias's own (presets, a select's options).
 * - `options`: a select's options, each with a label.
 * - `numberMode`: how a number is set (slider, box).
 * - `assumed`: a switch whose state is the last command, not a reading.
 * - `code`: a lock that wants a code, and its length.
 * - `speeds`: how many speeds a fan has.
 * - `locationSource`: where a location comes from.
 */
export const ALIAS_PART_SETTINGS = [
  'range',
  'offered',
  'options',
  'numberMode',
  'assumed',
  'code',
  'speeds',
  'locationSource',
] as const;

/** One setting a part may carry. */
export type AliasPartSetting = (typeof ALIAS_PART_SETTINGS)[number];

/** One part of a type: a field of one of its capabilities. */
export type AliasPartDef = {
  /** Its key in the file and the API: the state field in snake case (`target_temperature`). */
  readonly key: string;

  /** The capability the field belongs to. */
  readonly capability: CapabilityName;

  /**
   * The state fields it fills, in camel case as the capability's state has them: one, two for a
   * colour (hue and saturation), none for a press or a picture, which fills the whole state.
   */
  readonly fields: readonly string[];

  readonly kind: AliasPartKind;

  /** Whether the type cannot do without it. */
  readonly isRequired: boolean;

  /** What it is called, in English (the interface translates it). */
  readonly label: string;

  /** Its icon, from the platform's icon set. */
  readonly icon: string;

  /** For an `enum` fixed by the capability: its values, in order. */
  readonly values?: readonly string[];

  /** For an `enum` whose list is the alias's own: offered from its settings. */
  readonly isOffered?: boolean;

  /** Whether the field may be null (no preset, no effect, a number not known yet). */
  readonly isNullable?: boolean;

  /** For a `number`: the bounds no setting can widen (a percentage is 0 to 100). */
  readonly bounds?: { readonly min: number; readonly max: number };

  /** The unit it is shown in, when it always has the same one. */
  readonly unit?: string;

  /** The value a new Stored part starts with. */
  readonly initial: unknown;

  /** The settings it carries besides its source. */
  readonly settings: readonly AliasPartSetting[];

  /**
   * Parts added and removed together, by a shared name: a thermostat's low and high target are
   * one "Target range".
   */
  readonly group?: string;
};

/** Where a type is filed in the picker. */
export const ALIAS_TYPE_GROUPS = ['readings', 'controls', 'climate', 'media'] as const;

/** Where a type is filed in the picker. */
export type AliasTypeGroup = (typeof ALIAS_TYPE_GROUPS)[number];

/** Every type an alias can behave as. */
export const ALIAS_TYPE_IDS = [
  'sensor',
  'text',
  'binary_sensor',
  'device_tracker',
  'geo_location',
  'switch',
  'light',
  'fan',
  'cover',
  'lock',
  'button',
  'select',
  'number',
  'thermostat',
  'media_player',
  'camera',
  'image',
  'vacuum',
  'lawn_mower',
  'update',
  'custom',
] as const;

/** A type an alias can behave as. */
export type AliasTypeId = (typeof ALIAS_TYPE_IDS)[number];

/** One type an alias can behave as. */
export type AliasTypeDef = {
  readonly id: AliasTypeId;

  /** The domain its entity behaves as. */
  readonly domain: EntityDomain;

  readonly group: AliasTypeGroup;
  readonly label: string;

  /** The plural, for a list's group heading. */
  readonly plural: string;

  readonly icon: string;

  /** Words a search finds it by, besides its name ("heat" finds a thermostat). */
  readonly words: string;

  /** The capabilities it always carries. */
  readonly capabilities: readonly CapabilityName[];

  /** The capabilities it carries only when one of their parts is added. */
  readonly optionalCapabilities: readonly CapabilityName[];

  /** Its parts, required first, in the order they are shown. Empty for a custom type. */
  readonly parts: readonly AliasPartDef[];

  /** Whether it has a Display section (shown as, unit, precision). */
  readonly display?: 'numeric' | 'binary';
};

const RANGE: readonly AliasPartSetting[] = ['range'];
const OFFERED: readonly AliasPartSetting[] = ['offered'];
const NONE: readonly AliasPartSetting[] = [];

/**
 * Shorthand for a part.
 *
 * @param part - The part, without the defaults.
 * @returns The part.
 */
function part(
  part: Omit<AliasPartDef, 'settings'> & { readonly settings?: readonly AliasPartSetting[] },
): AliasPartDef {
  return { settings: NONE, ...part };
}

const ON = part({
  key: 'on',
  capability: 'on_off',
  fields: ['isOn'],
  kind: 'boolean',
  isRequired: true,
  label: 'On / off',
  icon: 'power',
  initial: false,
  settings: ['assumed'],
});

/**
 * An `on_off` part a type may add (a player or a camera that can be switched off).
 *
 * @returns The part, optional.
 */
const optionalOn = (): AliasPartDef => ({ ...ON, isRequired: false, settings: NONE });

