const TYPES_BY_ID: ReadonlyMap<AliasTypeId, AliasTypeDef> = new Map(
  ALIAS_TYPES.map((type) => [type.id, type]),
);

/**
 * One type, by its id.
 *
 * @param id - The type.
 * @returns Its definition.
 * @throws {Error} When no type has that id: an id the schema let through, so a bug.
 */
export function aliasType(id: AliasTypeId): AliasTypeDef {
  const found = TYPES_BY_ID.get(id);

  if (found === undefined) {
    throw new Error(`Unknown alias type ${id}`);
  }

  return found;
}

/**
 * One part of a type, by its key.
 *
 * @param type - The type.
 * @param key - The part's key.
 * @returns Its definition, or undefined when the type has no such part.
 */
export function aliasPartDef(type: AliasTypeDef, key: string): AliasPartDef | undefined {
  return type.parts.find((candidate) => candidate.key === key);
}

/** One field of a package's entity type, as a custom alias type sees it. */
export type AliasCustomField = {
  readonly key: string;
  readonly type: 'text' | 'number' | 'boolean' | 'choice' | 'timestamp';
  readonly label: string;
  readonly choices?: readonly { readonly value: string; readonly label: string }[] | undefined;
  readonly isOptional: boolean;
};

/**
 * The parts of a custom type: one per field of the package's entity type.
 *
 * @param fields - The entity type's state fields.
 * @returns The parts, in the fields' order.
 */
export function customAliasParts(fields: readonly AliasCustomField[]): AliasPartDef[] {
  return fields.map((field) =>
    part({
      key: snakeCase(field.key),
      capability: 'custom',
      fields: [field.key],
      kind:
        field.type === 'number'
          ? 'number'
          : field.type === 'boolean'
            ? 'boolean'
            : field.type === 'choice'
              ? 'enum'
              : 'text',
      isRequired: !field.isOptional,
      isNullable: true,
      label: field.label,
      icon: 'puzzle',
      ...(field.choices === undefined ? {} : { values: field.choices.map((c) => c.value) }),
      initial:
        field.type === 'number'
          ? 0
          : field.type === 'boolean'
            ? false
            : field.type === 'choice'
              ? (field.choices?.[0]?.value ?? null)
              : '',
    }),
  );
}

/**
 * A camel-case key in snake case: `targetTemperature` → `target_temperature`.
 *
 * @param key - The key.
 * @returns The same words, lower case, joined by underscores.
 */
export function snakeCase(key: string): string {
  return key.replace(/[A-Z]/gu, (letter) => `_${letter.toLowerCase()}`);
}

/**
 * The parts a type shows: its own, or a custom type's from its package entity type.
 *
 * @param type - The type.
 * @param customFields - For a custom type, the fields of its package entity type.
 * @returns The parts.
 */
export function aliasTypeParts(
  type: AliasTypeDef,
  customFields?: readonly AliasCustomField[],
): readonly AliasPartDef[] {
  return type.id === 'custom' ? customAliasParts(customFields ?? []) : type.parts;
}

/**
 * The capabilities an alias declares: the type's own, and each optional one with a part added.
 *
 * @param type - The type.
 * @param partKeys - The keys of the parts it has.
 * @returns The capabilities, in the type's order.
 */
export function aliasCapabilities(
  type: AliasTypeDef,
  partKeys: Iterable<string>,
): CapabilityName[] {
  const keys = new Set(partKeys);
  const optional = type.optionalCapabilities.filter((capability) =>
    type.parts.some((candidate) => candidate.capability === capability && keys.has(candidate.key)),
  );
  const own = [...type.capabilities];

  return [...new Set([...own, ...optional])];
}
